(function () { 'use strict'; var root = document.querySelector('article.tk-single, .tk-single-article'); if (!root) { return; } var STORE_KEY = 'tk:resume:v1'; var PATH = location.pathname; var MIN_PCT = 0.15; var MAX_PCT = 0.92; var MAX_AGE = 90 * 24 * 60 * 60 * 1000; function load() { try { return JSON.parse(localStorage.getItem(STORE_KEY)) || {}; } catch (e) { return {}; } } function save(store) { try { localStorage.setItem(STORE_KEY, JSON.stringify(store)); } catch (e) { } } var store = load(); var now = Date.now(); Object.keys(store).forEach(function (k) { if (!store[k] || (now - (store[k].t || 0)) > MAX_AGE) { delete store[k]; } }); function scrollPct() { var doc = document.documentElement; var height = doc.scrollHeight - doc.clientHeight; return height > 0 ? Math.min(1, Math.max(0, window.scrollY / height)) : 0; } var prior = store[PATH]; if (prior && prior.pct > MIN_PCT && prior.pct < MAX_PCT) { var pill = document.createElement('button'); pill.type = 'button'; pill.className = 'tk-resume'; pill.textContent = 'Resume where you left off — ' + Math.round(prior.pct * 100) + '%'; pill.setAttribute('aria-label', 'Resume where you left off, ' + Math.round(prior.pct * 100) + ' percent'); document.body.appendChild(pill); var dismiss = function () { if (pill.parentNode) { pill.parentNode.removeChild(pill); } }; pill.addEventListener('click', function () { var target = (document.documentElement.scrollHeight - document.documentElement.clientHeight) * prior.pct; window.scrollTo({ top: target, behavior: 'smooth' }); dismiss(); }); var onScrollDismiss = function () { dismiss(); window.removeEventListener('scroll', onScrollDismiss); }; setTimeout(function () { window.addEventListener('scroll', onScrollDismiss); }, 800); setTimeout(dismiss, 15000); } var pending = false; var timer = null; function schedule() { if (pending) { return; } pending = true; clearTimeout(timer); timer = setTimeout(function () { requestAnimationFrame(function () { pending = false; var pct = scrollPct(); if (pct < MIN_PCT || pct > MAX_PCT) { if (store[PATH]) { delete store[PATH]; save(store); } return; } store[PATH] = { pct: pct, t: Date.now() }; save(store); }); }, 400); } window.addEventListener('scroll', schedule, { passive: true }); window.addEventListener('beforeunload', function () { var pct = scrollPct(); if (pct >= MIN_PCT && pct <= MAX_PCT) { store[PATH] = { pct: pct, t: Date.now() }; save(store); } }); })();